import{_ as o,C as i,o as a,c as d,a2 as e,b as n,w as l,a as s,E as c,a3 as h}from"./chunks/framework.DToEn73J.js";const k=JSON.parse('{"title":"Kill Switch 熔断","description":"","frontmatter":{"title":"Kill Switch 熔断","chapter":"5.4","order":4,"summary":"全局熔断在运行时紧急中止 Agent，与事后回滚互补而非替代。"},"headers":[],"relativePath":"05-safety-governance/kill-switch.md","filePath":"05-safety-governance/kill-switch.md","lastUpdated":1787724133000}'),E={name:"05-safety-governance/kill-switch.md"};function u(A,t,p,g,_,b){const r=i("Mermaid");return a(),d("div",null,[t[1]||(t[1]=e('<h1 id="kill-switch-熔断" tabindex="-1">Kill Switch 熔断 <a class="header-anchor" href="#kill-switch-熔断" aria-label="Permalink to &quot;Kill Switch 熔断&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>Kill Switch（熔断 / circuit breaker）是运行时机制：在检测到失控、超支或危险信号时，立即中止整个 Agent Loop 或单个 Tool 调用，防止损害扩大。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><p><strong>触发信号</strong>：预算超阈值（见 1.4 预算控制）、连续错误率超界、命中 Guardrails 高危清单、人工急停按钮。</p><p><strong>设计要点</strong>：</p><ul><li>全局开关置于 Orchestrator，信号通过共享状态（如 redis）广播给所有 Worker；</li><li>熔断后进入 <code>OPEN</code> 态，新请求直接拒绝，避免雪崩；</li><li>提供半开 <code>HALF_OPEN</code> 探测，确认恢复后回到 <code>CLOSED</code>。</li></ul>',7)),(a(),n(h,null,{default:l(()=>[c(r,{id:"mermaid-35",class:"mermaid",graph:"stateDiagram-v2%0A%20%20%20%20%5B*%5D%20--%3E%20CLOSED%0A%20%20%20%20CLOSED%20--%3E%20OPEN%3A%20%E8%A7%A6%E5%8F%91%E7%86%94%E6%96%AD%E6%9D%A1%E4%BB%B6%0A%20%20%20%20OPEN%20--%3E%20HALF_OPEN%3A%20%E5%86%B7%E5%8D%B4%E6%9C%9F%E7%BB%93%E6%9D%9F%0A%20%20%20%20HALF_OPEN%20--%3E%20CLOSED%3A%20%E6%8E%A2%E6%B5%8B%E5%81%A5%E5%BA%B7%0A%20%20%20%20HALF_OPEN%20--%3E%20OPEN%3A%20%E6%8E%A2%E6%B5%8B%E5%A4%B1%E8%B4%A5%0A%20%20%20%20OPEN%20--%3E%20%5B*%5D%3A%20%E4%BA%BA%E5%B7%A5%E5%A4%8D%E4%BD%8D%0A"})]),fallback:l(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=e('<p>最小实现：Agent Loop 每轮检查 <code>kill_switch.is_open()</code>，为真则抛 <code>AgentHalt</code> 并清理进行中 Tool。</p><h2 id="为什么" tabindex="-1">为什么 <a class="header-anchor" href="#为什么" aria-label="Permalink to &quot;为什么&quot;">​</a></h2><p>不做熔断时，受 Prompt Injection 诱导的 Agent 会持续调用付费 Tool 或外发数据，损失随时间线性增长；人工发现前已无法止损。</p><h2 id="kill-switch-vs-rollback" tabindex="-1">Kill Switch vs Rollback <a class="header-anchor" href="#kill-switch-vs-rollback" aria-label="Permalink to &quot;Kill Switch vs Rollback&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Kill Switch（熔断）</th><th>Audit-Rollback（回滚）</th></tr></thead><tbody><tr><td>时机</td><td>运行时，损害发生中</td><td>事后，损害已发生</td></tr><tr><td>目标</td><td>立即止损、阻止扩大</td><td>恢复到一致状态</td></tr><tr><td>触发</td><td>阈值/信号/人工</td><td>异常检测/人工</td></tr><tr><td>可逆性</td><td>复位即恢复服务</td><td>需执行逆操作</td></tr><tr><td>依赖</td><td>全局共享状态</td><td>Checkpoint 快照</td></tr></tbody></table><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li>认为有回滚就不需要熔断：回滚无法阻止进行中的外发或扣费。</li><li>熔断粒度太粗，单次坏 Tool 拖垮整个系统。</li></ul><h2 id="业界实现对照" tabindex="-1">业界实现对照 <a class="header-anchor" href="#业界实现对照" aria-label="Permalink to &quot;业界实现对照&quot;">​</a></h2><ul><li><strong>LangGraph</strong>：可通过 <code>interrupt()</code> 在节点边界暂停，等价于受控熔断点。</li><li><strong>OpenAI Agents SDK</strong>：<code>RunResult</code> 提供 <code>cancel()</code> 中止正在进行的 run。</li><li>参考：<a href="https://docs.anthropic.com/en/docs/agents-and-tools/agent-safety" target="_blank" rel="noreferrer">https://docs.anthropic.com/en/docs/agents-and-tools/agent-safety</a></li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/fk-ai-agent/05-safety-governance/audit-rollback">/05-safety-governance/audit-rollback</a></li><li><a href="/fk-ai-agent/01-agent-basics/budget-control">/01-agent-basics/budget-control</a></li><li><a href="/fk-ai-agent/05-safety-governance/guardrails">/05-safety-governance/guardrails</a></li></ul><hr><p><em>最后核实日期：2026-08-26</em></p>',13))])}const m=o(E,[["render",u]]);export{k as __pageData,m as default};
